files.constant/physicalProperties:
FoamFile
{
    format ascii;
    class dictionary;
    object physicalProperties;
}

thermoType
{
    type hePsiThermo;
    mixture pureMixture;
    transport const;
    thermo eConst;
    equationOfState perfectGas;
    specie specie;
    energy sensibleInternalEnergy;
}
mixture
{
    specie { molWeight 28.970253024924183; }
    thermodynamics { Cv 717.5000000000001; Hf 0; }
    transport { mu 0; Pr 1; }
}

files.constant/momentumTransport:
FoamFile
{
    format ascii;
    class dictionary;
    object momentumTransport;
}

simulationType laminar;

files.system/fvSchemes:
FoamFile
{
    format ascii;
    class dictionary;
    object fvSchemes;
}

fluxScheme Kurganov;
ddtSchemes { default Euler; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes
{
    default linear;
    reconstruct(rho) Minmod;
    reconstruct(U) Minmod;
    reconstruct(T) Minmod;
}
snGradSchemes { default corrected; }

files.system/fvSolution:
FoamFile
{
    format ascii;
    class dictionary;
    object fvSolution;
}

solvers
{
    "rho.*" { solver diagonal; }
    "(U|e).*" { solver diagonal; }
}
PIMPLE { nOuterCorrectors 1; }

files.system/controlDict:
FoamFile
{
    format ascii;
    class dictionary;
    object controlDict;
}

solver shockFluid;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 0.006;
deltaT 1e-08;
adjustTimeStep yes;
maxCo 0.4;
maxDeltaT 2e-06;
writeControl adjustableRunTime;
writeInterval 0.00025;
purgeWrite 0;
writeFormat ascii;
writePrecision 14;
writeCompression off;
timePrecision 14;
runTimeModifiable false;
